{"path":"/root/output/validate_result.py","content":"from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

src = '/root/data/workbook.xlsx'
out = '/root/output/result.xlsx'
orig = load_workbook(src, data_only=False)
wb = load_workbook(out, data_only=False)
ws = wb['Task']

print('Original sheets:', orig.sheetnames)
print('Result sheets:', wb.sheetnames)
if wb.sheetnames != orig.sheetnames:
    raise AssertionError('Sheet names changed or new sheets added')

ranges = ['H12:L17', 'H19:L24', 'H26:L31', 'H35:L40', 'H42:L47', 'H50:L50']
for rng in ranges:
    missing = []
    for row in ws[rng]:
        for cell in row:
            if not (isinstance(cell.value, str) and cell.value.startswith('=')):
                missing.append((cell.coordinate, cell.value))
    print(f'{rng}: formula cells checked = {sum(1 for row in ws[rng] for _ in row)}, missing/non-formula = {missing}')
    if missing:
        raise AssertionError(f'Non-formula cells in {rng}: {missing}')

lookup_ranges = ['H12:L17', 'H19:L24', 'H26:L31']
for rng in lookup_ranges:
    bad = []
    for row in ws[rng]:
        for cell in row:
            v = cell.value
            if 'MATCH(' not in v or 'INDEX(' not in v or 'Data!' not in v:
                bad.append((cell.coordinate, v))
    print(f'{rng}: lookup formulas include INDEX/MATCH/Data references')
    if bad:
        raise AssertionError(f'Bad lookup formulas in {rng}: {bad}')

bad_weighted = []
for cell in ws['H50:L50'][0]:
    if 'SUMPRODUCT(' not in cell.value:
        bad_weighted.append((cell.coordinate, cell.value))
print('H50:L50 SUMPRODUCT check:', 'OK' if not bad_weighted else bad_weighted)
if bad_weighted:
    raise AssertionError('Missing SUMPRODUCT in weighted mean formulas')

samples = {
    'lookup_finished': ['H12', 'L17'],
    'lookup_scrap': ['H19', 'L24'],
    'lookup_capacity': ['H26', 'L31'],
    'slack': ['H35', 'L40'],
    'stats': ['H42', 'H43', 'H44', 'H45', 'H46', 'H47'],
    'weighted': ['H50', 'L50'],
}
print('\nFormula samples:')
for name, coords in samples.items():
    print(name)
    for coord in coords:
        print(' ', coord, ws[coord].value)

# Additional exact expected spot checks
expected = {
    'H12': '=INDEX(Data!$H$21:$L$38,MATCH($D12,Data!$D$21:$D$38,0),MATCH(H$10,Data!$H$4:$L$4,0))',
    'L31': '=INDEX(Data!$H$21:$L$38,MATCH($D31,Data!$D$21:$D$38,0),MATCH(L$10,Data!$H$4:$L$4,0))',
    'H35': '=(H12-H19)/H26*100',
    'L40': '=(L17-L24)/L31*100',
    'H42': '=MIN(H35:H40)',
    'H43': '=MAX(H35:H40)',
    'H44': '=MEDIAN(H35:H40)',
    'H45': '=AVERAGE(H35:H40)',
    'H46': '=PERCENTILE(H35:H40,0.25)',
    'H47': '=PERCENTILE(H35:H40,0.75)',
    'H50': '=SUMPRODUCT(H35:H40,H26:H31)/SUM(H26:H31)',
}
for coord, formula in expected.items():
    actual = ws[coord].value
    if actual != formula:
        raise AssertionError(f'{coord} expected {formula!r}, got {actual!r}')
print('\nAll validation checks passed.')
